INSERT INTO projects (slug, nome, imagem, tecnologias, link_linkedin, link_github, link_ver_projeto, descricao_pt, descricao_en, data_pt, data_en, ordem, publicado) VALUES ('barberweb', 'BarberWeb', '/mockup/m-uiboost.webp', '["HTML5","CSS","Sass","JavaScript","UX/UI"]', 'https://www.linkedin.com/posts/luiz-antonio-souza-5000a226b_desenvolvimentoweb-frontend-educaaexaeto-activity-7199779916848975872-c5vG?utm_source=share&utm_medium=member_desktop', 'https://github.com/LuixzSouza/CabeleireiroPratic', 'https://cabeleireiroluiz.netlify.app', 'Este projeto foi desenvolvido com o objetivo de criar um site funcional e atraente para um salão de barbearia, oferecendo serviços de corte de cabelo e barba. Além de ser um projeto acadêmico integrador, que uniu estudantes do 4º e 2º período da faculdade, foi também uma oportunidade de praticar e aprimorar habilidades individuais em design e codificação, após a necessidade de reconstruir o projeto sem dados pessoais de terceiros, OBS: essas imagem foram criada com Inteligência Artificial.', 'This project aimed to create a functional and appealing website for a barbershop, offering haircut and beard services. Besides being an integrative academic project that brought together 4th- and 2nd-semester college students, it was also a chance to practice and improve individual design and coding skills, after the need to rebuild it without third parties\' personal data. NOTE: these images were created with Artificial Intelligence.', '14 de Outubro 2024', 'October 14, 2024', 20, 1);
