INSERT INTO projects (slug, nome, imagem, tecnologias, link_linkedin, link_github, link_ver_projeto, descricao_pt, descricao_en, data_pt, data_en, ordem, publicado) VALUES ('superget', 'SuperGet', '/mockup/m-superget.webp', '["HTML5","CSS3","Sass","JavaScript","React"]', 'https://www.linkedin.com/posts/luiz-antonio-souza-5000a226b_react-frontenddevelopment-webdevelopment-activity-7199046285767651328--fJN?utm_source=share&utm_medium=member_desktop', 'https://github.com/LuixzSouza/SuperGetReact', 'https://supergetluiz.netlify.app', 'Este projeto foi desenvolvido como parte de um exercício pessoal em React para aprimorar minhas habilidades de codificação e entender melhor os padrões de desenvolvimento web em React. Ele apresenta uma interface do produto SuperGet.', 'This project was built as a personal React exercise to sharpen my coding skills and better understand React web development patterns. It presents an interface for the SuperGet product.', '14 de Outubro 2024', 'October 14, 2024', 31, 1);
INSERT INTO projects (slug, nome, imagem, tecnologias, link_linkedin, link_github, link_ver_projeto, descricao_pt, descricao_en, data_pt, data_en, ordem, publicado) VALUES ('rede', 'Rede', '/mockup/m-rede.webp', '["HTML5","CSS3","Sass","JavaScript","React","Next.js","Tailwind","Swiper"]', 'https://www.linkedin.com/in/luiz-antonio-souza-5000a226b/', 'https://github.com/LuixzSouza/REDE-Site', 'https://redeluiz.netlify.app', 'Este projeto é uma interface moderna e funcional, inspirada em plataformas de redes e serviços financeiros, com foco na performance e experiência do usuário. Desenvolvido com Next.js, Tailwind CSS, e Swiper, ele oferece navegação fluida e design responsivo.', 'This project is a modern, functional interface inspired by network and financial service platforms, focused on performance and user experience. Built with Next.js, Tailwind CSS and Swiper, it offers smooth navigation and a responsive design.', '12 de janeiro 2024', 'January 12, 2024', 32, 1);
INSERT INTO projects (slug, nome, imagem, tecnologias, link_linkedin, link_github, link_ver_projeto, descricao_pt, descricao_en, data_pt, data_en, ordem, publicado) VALUES ('itau', 'Itau', '/mockup/m-java-ong-trabalho.webp', '["HTML5","CSS3","Sass","JavaScript","React","Next.js","Tailwind","Swiper"]', 'https://www.linkedin.com/in/luiz-antonio-souza-5000a226b/', 'https://github.com/LuixzSouza/Itau-Site', 'https://itauluiz.netlify.app', 'Este projeto foi inspirado no site de uma instituição financeira, buscando recriar uma interface moderna e responsiva, com foco na experiência do usuário e na performance. Ele foi desenvolvido com Next.js e Tailwind CSS, aproveitando o melhor dessas tecnologias para entregar um design elegante e funcional', 'This project was inspired by a financial institution\'s website, aiming to recreate a modern, responsive interface focused on user experience and performance. It was built with Next.js and Tailwind CSS, leveraging the best of these technologies to deliver an elegant, functional design.', '12 de janeiro 2024', 'January 12, 2024', 33, 1);
INSERT INTO projects (slug, nome, imagem, tecnologias, link_linkedin, link_github, link_ver_projeto, descricao_pt, descricao_en, data_pt, data_en, ordem, publicado) VALUES ('more-talent', 'More | Talent', '/mockup/m-moretalent.webp', '["HTML5","CSS3","Sass","JavaScript","React","Next.js","Tailwind","Swiper"]', 'https://www.linkedin.com/posts/luiz-antonio-souza-5000a226b_m%C3%B4re-talent-tech-descri%C3%A7%C3%A3o-do-projeto-activity-7212050959210860545-mhiu?utm_source=share&utm_medium=member_desktop', 'https://moretalentsluiz.netlify.app', 'https://moretalentsluiz.netlify.app', 'Este projeto, desenvolvido com Next.js e Tailwind CSS, foi criado com o objetivo de aprimorar minhas habilidades no desenvolvimento web. Ele simula uma página inicial de um curso completo em design de produto digital, focado no processo de Design Centrado no Usuário. A página inclui uma seção de pré-cadastro, destaca parcerias com grandes empresas e apresenta um layout moderno e responsivo', 'This project, built with Next.js and Tailwind CSS, was created to improve my web development skills. It simulates a homepage for a complete digital product design course, focused on the User-Centered Design process. The page includes a pre-registration section, highlights partnerships with major companies, and features a modern, responsive layout.', '08 de Outubro 2024', 'October 8, 2024', 34, 1);
INSERT INTO projects (slug, nome, imagem, tecnologias, link_linkedin, link_github, link_ver_projeto, descricao_pt, descricao_en, data_pt, data_en, ordem, publicado) VALUES ('lanistar', 'Lanistar', '/mockup/m-lanistar.webp', '["HTML5","CSS3","Sass","JavaScript","React","Next.js","Tailwind","Swiper"]', 'https://www.linkedin.com/in/luiz-antonio-souza-5000a226b/', 'https://github.com/LuixzSouza/lanistarluiz', 'https://lanistarluiz.netlify.app', 'Este projeto foi desenvolvido para simular a interface de uma plataforma financeira moderna e inovadora. Ele combina design minimalista e responsividade para oferecer uma experiência de usuário intuitiva e envolvente.', 'This project was built to simulate the interface of a modern, innovative financial platform. It combines minimalist design and responsiveness to deliver an intuitive, engaging user experience.', '12 de janeiro 2024', 'January 12, 2024', 35, 1);
INSERT INTO projects (slug, nome, imagem, tecnologias, link_linkedin, link_github, link_ver_projeto, descricao_pt, descricao_en, data_pt, data_en, ordem, publicado) VALUES ('tecsany', 'Tecsany', '/mockup/m-spiderman2.webp', '["HTML5","CSS3","Sass","JavaScript","React","Next.js","Tailwind","Swiper"]', 'https://www.linkedin.com/in/luiz-antonio-souza-5000a226b/', 'https://github.com/LuixzSouza/tecsanyluiz', 'https://tecsanyluiz.netlify.app', 'Este projeto foi desenvolvido para apresentar uma plataforma focada em tecnologia, com design moderno e responsivo. O objetivo foi criar uma interface amigável que combina funcionalidade com uma navegação intuitiva e eficiente.', 'This project was built to present a technology-focused platform with a modern, responsive design. The goal was to create a friendly interface that combines functionality with intuitive, efficient navigation.', '12 de janeiro 2024', 'January 12, 2024', 36, 1);
INSERT INTO projects (slug, nome, imagem, tecnologias, link_linkedin, link_github, link_ver_projeto, descricao_pt, descricao_en, data_pt, data_en, ordem, publicado) VALUES ('latam-airlines', 'Latam Airlines', '/mockup/m-latamairlines.webp', '["HTML5","CSS3","Sass","JavaScript","React","Next.js","Tailwind","Swiper"]', 'https://www.linkedin.com/in/luiz-antonio-souza-5000a226b/', 'https://github.com/LuixzSouza/LatamAirLanes', 'https://latamairlinesluiz.netlify.app', 'Este projeto foi desenvolvido para simular a interface de uma plataforma de reservas de voo, inspirada na identidade visual da Latam Airlines. A ideia foi criar uma aplicação moderna e intuitiva, com foco em usabilidade e design responsivo, proporcionando uma experiência agradável aos usuários.', 'This project was built to simulate a flight booking platform interface, inspired by Latam Airlines\' visual identity. The idea was to create a modern, intuitive application focused on usability and responsive design, providing a pleasant user experience.', '12 de janeiro 2024', 'January 12, 2024', 37, 1);
INSERT INTO projects (slug, nome, imagem, tecnologias, link_linkedin, link_github, link_ver_projeto, descricao_pt, descricao_en, data_pt, data_en, ordem, publicado) VALUES ('spider-man-2', 'Spider Man 2', '/mockup/m-java-poo.webp', '["HTML5","CSS3","Sass","JavaScript","React","Next.js","Tailwind","Swiper"]', 'https://www.linkedin.com/in/luiz-antonio-souza-5000a226b/', 'https://github.com/LuixzSouza/spidermanluiz', 'https://spidermanluiz.netlify.app', 'Este projeto foi desenvolvido para criar uma landing page dinâmica e envolvente, inspirada no universo do Spider Man. O foco foi na criação de uma experiência visual impactante e interativa, utilizando técnicas modernas de desenvolvimento web.', 'This project was built to create a dynamic, engaging landing page inspired by the Spider-Man universe. The focus was on crafting a striking, interactive visual experience using modern web development techniques.', '12 de janeiro 2024', 'January 12, 2024', 38, 1);
INSERT INTO projects (slug, nome, imagem, tecnologias, link_linkedin, link_github, link_ver_projeto, descricao_pt, descricao_en, data_pt, data_en, ordem, publicado) VALUES ('java-sql', 'JAVA | SQL', '/mockup/m-javasql.webp', '["Faculdade","JAVA","SQL"]', 'https://www.linkedin.com/in/luiz-antonio-souza-5000a226b/', 'https://github.com/LuixzSouza/JAVA-SQL', 'https://github.com/LuixzSouza/JAVA-SQL', 'Este projeto desenvolve uma aplicação Java com Maven, Hibernate e MySQL, estruturando a classe Veículo e implementando operações de CRUD (inserção, consulta, remoção e atualização). Ele permite armazenar e gerenciar dados de veículos de forma eficiente em um banco de dados relacional.', 'This project builds a Java application with Maven, Hibernate and MySQL, structuring the Vehicle class and implementing CRUD operations (insert, query, delete and update). It allows storing and managing vehicle data efficiently in a relational database.', '12 de janeiro 2024', 'January 12, 2024', 39, 1);
INSERT INTO projects (slug, nome, imagem, tecnologias, link_linkedin, link_github, link_ver_projeto, descricao_pt, descricao_en, data_pt, data_en, ordem, publicado) VALUES ('python-botnotepad-test', 'Python BotNotepad Test', '/mockup/m-pythonbotnotepad.webp', '["Python"]', 'https://www.linkedin.com/in/luiz-antonio-souza-5000a226b/', 'https://github.com/LuixzSouza/Python-BotNotepad-Test', 'https://github.com/LuixzSouza/Python-BotNotepad-Test', 'Este projeto contém um bot simples em Python que utiliza a biblioteca PyAutoGUI para automatizar tarefas no computador. Especificamente, este bot abre o Bloco de Notas (Notepad) no Windows, escreve uma mensagem predefinida e simula a digitação no programa. O bot é útil para demonstração de automação de interface gráfica e interação com aplicativos desktop.', 'This project contains a simple Python bot that uses the PyAutoGUI library to automate tasks on the computer. Specifically, the bot opens Notepad on Windows, writes a predefined message and simulates typing in the program. It\'s useful for demonstrating GUI automation and interaction with desktop applications.', '12 de janeiro 2024', 'January 12, 2024', 40, 1);
INSERT INTO projects (slug, nome, imagem, tecnologias, link_linkedin, link_github, link_ver_projeto, descricao_pt, descricao_en, data_pt, data_en, ordem, publicado) VALUES ('exercicios-javascript', 'Exercicios JavaScript', '/mockup/m-exerciciosjs.webp', '["Node.js","JavaScript"]', 'https://www.linkedin.com/in/luiz-antonio-souza-5000a226b/', 'https://github.com/LuixzSouza/Exercicio_JavaScript-Node.js', 'https://github.com/LuixzSouza/Exercicio_JavaScript-Node.js', 'Varios exercicos para treinar o desenvolvimento em JavaScript e Node.js', 'Several exercises to practice development in JavaScript and Node.js.', '12 de janeiro 2024', 'January 12, 2024', 41, 1);
INSERT INTO projects (slug, nome, imagem, tecnologias, link_linkedin, link_github, link_ver_projeto, descricao_pt, descricao_en, data_pt, data_en, ordem, publicado) VALUES ('java-ong-trabalho-facul', 'JAVA | ONG | Trabalho Facul', '/projects/Trabalho-Java-ONG.webp', '["Faculdade","JAVA"]', 'https://www.linkedin.com/in/luiz-antonio-souza-5000a226b/', 'https://github.com/LuixzSouza/Sistema-de-Gerenciamento-de-ONG', 'https://github.com/LuixzSouza/Sistema-de-Gerenciamento-de-ONG', 'Este sistema foi desenvolvido para facilitar o processo de agendamento de doações para Organizações Não Governamentais (ONGs). O objetivo é permitir que os doadores registrem suas informações, cadastrem itens que irão doar (como roupas, alimentos, etc.), e agendem a data para a entrega ou retirada das doações. O sistema também valida as entradas de dados, como CPF e data, garantindo maior precisão nas informações fornecidas.', 'This system was built to streamline the donation scheduling process for Non-Governmental Organizations (NGOs). The goal is to let donors register their information, list the items they\'ll donate (such as clothing, food, etc.), and schedule a date for delivery or pickup. The system also validates data entries, such as CPF and date, ensuring greater accuracy in the information provided.', '12 de janeiro 2024', 'January 12, 2024', 42, 1);
INSERT INTO projects (slug, nome, imagem, tecnologias, link_linkedin, link_github, link_ver_projeto, descricao_pt, descricao_en, data_pt, data_en, ordem, publicado) VALUES ('java-poo-trabalho-facul', 'JAVA | POO | Trabalho Facul', '/projects/Trabalho-POO-Java.webp', '["JAVA","Atividade"]', 'https://www.linkedin.com/in/luiz-antonio-souza-5000a226b/', 'https://github.com/LuixzSouza/LISTA_EXERCICIOS_POO-4p---Luiz-Ant-nio-de-Souza-', 'https://github.com/LuixzSouza/LISTA_EXERCICIOS_POO-4p---Luiz-Ant-nio-de-Souza-', 'Atividades feita para entregar ao professor', 'Assignments made to submit to the professor.', '12 de janeiro 2024', 'January 12, 2024', 43, 1);
INSERT INTO projects (slug, nome, imagem, tecnologias, link_linkedin, link_github, link_ver_projeto, descricao_pt, descricao_en, data_pt, data_en, ordem, publicado) VALUES ('modulo-javascript', 'Modulo JavaScript', '/projects/Modulo-JavaScript.webp', '["JavaScript","Ajuda"]', 'https://www.linkedin.com/posts/luiz-antonio-souza-5000a226b_javascript-webdevelopment-codingjourney-activity-7200155836277542912-faey?utm_source=share&utm_medium=member_desktop', 'https://github.com/LuixzSouza/ModuloJavaScript', 'https://github.com/LuixzSouza/ModuloJavaScript', 'Criei um repositório com módulos dedicados a diferentes tópicos de JavaScript, começando com uma introdução simples e avançando para manipulações complexas do DOM e armazenamento local. ', 'I created a repository with modules dedicated to different JavaScript topics, starting with a simple introduction and advancing to complex DOM manipulation and local storage.', '24 de Maio 2024', 'May 24, 2024', 44, 1);
INSERT INTO certificates (slug, course, issuer, data_curso, file, image, descricao_pt, descricao_en, skills, ordem, publicado) VALUES ('especialista-php', 'Especialista PHP', 'Rocketseat', '2024', '/certificates/Certificado_php_Luiz.pdf', '/certificates/certificatesImg/Certificado_php_Luiz.webp', 'Formação focada em desenvolvimento back-end com PHP: fundamentos da linguagem, programação orientada a objetos, integração com banco de dados MySQL e boas práticas para construir aplicações web seguras e organizadas.', 'Back-end development training focused on PHP: language fundamentals, object-oriented programming, MySQL database integration and best practices to build secure, well-organized web applications.', '["PHP","POO","MySQL","Back-end","Web"]', 0, 1);
INSERT INTO certificates (slug, course, issuer, data_curso, file, image, descricao_pt, descricao_en, skills, ordem, publicado) VALUES ('aws-academy-cloud-foundations', 'AWS Academy Cloud Foundations', 'AWS Academy', '2024', '/certificates/Certificado_AWS.pdf', '/certificates/certificatesImg/Certificado_AWS.webp', 'Fundamentos de computação em nuvem com a Amazon Web Services: principais serviços, segurança, arquitetura, precificação e o modelo de responsabilidade compartilhada da AWS.', 'Cloud computing fundamentals with Amazon Web Services: core services, security, architecture, pricing and the AWS shared responsibility model.', '["AWS","Cloud","Infraestrutura","Segurança"]', 1, 1);
INSERT INTO certificates (slug, course, issuer, data_curso, file, image, descricao_pt, descricao_en, skills, ordem, publicado) VALUES ('criacao-de-sites', 'Criação de Sites', 'Bradesco', '2024', '/certificates/Certificado-Bradesco.pdf', '/certificates/certificatesImg/Certificado-Bradesco.webp', 'Curso sobre os fundamentos da criação de sites: estruturação com HTML, estilização com CSS e os princípios essenciais para colocar uma página no ar de forma profissional.', 'A course on the fundamentals of website creation: structuring with HTML, styling with CSS and the essential principles to launch a page professionally.', '["HTML","CSS","Web Design"]', 2, 1);
INSERT INTO certificates (slug, course, issuer, data_curso, file, image, descricao_pt, descricao_en, skills, ordem, publicado) VALUES ('melhor-arte-visual-game-jam', 'Melhor Arte Visual — Game Jam', 'Game Jam', '2024', '/certificates/Certificado_GameJam.pdf', '/certificates/certificatesImg/Certificado_GameJam.webp', 'Reconhecimento de Melhor Arte Visual em uma Game Jam — uma maratona de desenvolvimento onde uma equipe cria um jogo do zero em tempo limitado, com destaque para a direção visual do projeto.', 'Best Visual Art award at a Game Jam — a development marathon where a team builds a game from scratch in limited time, recognized here for the project\'s visual direction.', '["Design","Arte Visual","UI","Trabalho em equipe"]', 3, 1);
INSERT INTO certificates (slug, course, issuer, data_curso, file, image, descricao_pt, descricao_en, skills, ordem, publicado) VALUES ('codeboost-front-end', 'CodeBoost Front-End', 'William Moreira', '2023', '/certificates/Certificado_Boost_Luiz.pdf', '/certificates/certificatesImg/Certificado_Boost_Luiz.webp', 'Imersão prática em desenvolvimento front-end, reforçando HTML, CSS e JavaScript com foco na construção de interfaces modernas, responsivas e fiéis ao design.', 'Hands-on front-end development bootcamp, reinforcing HTML, CSS and JavaScript with a focus on building modern, responsive interfaces faithful to the design.', '["HTML","CSS","JavaScript","Front-end","Responsivo"]', 4, 1);
INSERT INTO certificates (slug, course, issuer, data_curso, file, image, descricao_pt, descricao_en, skills, ordem, publicado) VALUES ('normas-da-abnt-modulo-i', 'Normas da ABNT (Módulo I)', 'Univas Virtual', '2023', '/certificates/Certificado_ABNT_Univas_Luiz.pdf', '/certificates/certificatesImg/Certificado_ABNT_Univas_Luiz.webp', 'Curso sobre as normas da ABNT para trabalhos acadêmicos: formatação, citações, referências e a estrutura padrão exigida em documentos técnicos e científicos.', 'A course on Brazil\'s ABNT standards for academic work: formatting, citations, references and the standard structure required in technical and scientific documents.', '["ABNT","Documentação","Escrita técnica"]', 5, 1);
INSERT INTO testimonials (nome, role_pt, role_en, quote_pt, quote_en, image, ordem, publicado) VALUES ('Eduardo Souza', 'Visual Design', 'Visual Design', 'Estou impressionado com o crescimento e a evolução do Luiz como desenvolvedor. Ele tem uma dedicação incrível e resolve tarefas complexas com eficiência e clareza. Destaca-se pela atenção aos detalhes, entregando resultados pixel perfect e seguindo com precisão os projetos de design. Apesar de iniciar sua jornada, tenho certeza de que tem um futuro brilhante pela frente.', 'I\'m impressed by Luiz\'s growth and evolution as a developer. He has incredible dedication and solves complex tasks with efficiency and clarity. He stands out for his attention to detail, delivering pixel-perfect results and faithfully following the design files. Even though he\'s early in his journey, I\'m sure he has a bright future ahead.', '/image/edu.webp', 0, 1);
INSERT INTO testimonials (nome, role_pt, role_en, quote_pt, quote_en, image, ordem, publicado) VALUES ('Lennon Mauricio', 'Produtor de Vídeo', 'Video Producer', 'Trabalhei com Luiz em um projeto e fiquei impressionado com sua dedicação e profissionalismo. Ele é muito aberto a feedbacks, sempre disposto a fazer os ajustes necessários para garantir o melhor resultado. Além de dominar boas práticas, é colaborativo e tornou o trabalho em equipe mais fluido. Seu comprometimento foi fundamental para a entrega do projeto.', 'I worked with Luiz on a project and was impressed by his dedication and professionalism. He\'s very open to feedback, always willing to make the adjustments needed to ensure the best result. Beyond mastering good practices, he\'s collaborative and made teamwork smoother. His commitment was key to delivering the project.', '/image/lennon.webp', 1, 1);
INSERT INTO testimonials (nome, role_pt, role_en, quote_pt, quote_en, image, ordem, publicado) VALUES ('Renan Carlos', 'Estudante de SI', 'IS Student', 'O Luiz é um cara que eu admiro muito. São nítidos os seus esforços e a vontade de se tornar um profissional cada vez melhor — sempre motivando os colegas com sua transparência e bondade.', 'Luiz is someone I really admire. His effort and his drive to become an ever-better professional are clear — always motivating his colleagues with his transparency and kindness.', '/image/renan.webp', 2, 1);
