INSERT INTO milestones (year_pt, year_en, title_pt, title_en, desc_pt, desc_en, techs, ordem, publicado) VALUES ('2021', '2021', 'O início autodidata', 'The self-taught start', 'A lógica de programação deixou de ser teoria e virou paixão. O primeiro contato com HTML, CSS e JavaScript abriu as portas da web.', 'Programming logic stopped being theory and became a passion. The first contact with HTML, CSS and JavaScript opened the doors to the web.', '["HTML5","CSS3","JavaScript"]', 0, 1);
INSERT INTO milestones (year_pt, year_en, title_pt, title_en, desc_pt, desc_en, techs, ordem, publicado) VALUES ('2022', '2022', 'Aprofundamento no Front-End', 'Going deeper into Front-End', 'Foco total em interfaces modernas e componentizadas, com os primeiros aplicativos reais saindo do papel.', 'Full focus on modern, component-based interfaces, with the first real apps coming to life.', '["React","Next.js","Tailwind"]', 1, 1);
INSERT INTO milestones (year_pt, year_en, title_pt, title_en, desc_pt, desc_en, techs, ordem, publicado) VALUES ('2023', '2023', 'Design & arquitetura', 'Design & architecture', 'Ingresso em Sistemas de Informação (UNIVÁS). O código encontra UI/UX, prototipação e os fundamentos de arquitetura de software.', 'Started Information Systems (UNIVÁS). Code meets UI/UX, prototyping and the fundamentals of software architecture.', '["Figma","Webflow","Python","Linux"]', 2, 1);
INSERT INTO milestones (year_pt, year_en, title_pt, title_en, desc_pt, desc_en, techs, ordem, publicado) VALUES ('2024', '2024', 'Back-end, sistemas & cloud', 'Back-end, systems & cloud', 'Projetos em produção: plataformas completas e dinâmicas, com banco de dados estruturado e primeiros passos na nuvem.', 'Projects in production: complete, dynamic platforms with structured databases and first steps into the cloud.', '["PHP","MySQL","AWS"]', 3, 1);
INSERT INTO milestones (year_pt, year_en, title_pt, title_en, desc_pt, desc_en, techs, ordem, publicado) VALUES ('2025', '2025', 'Maturidade full-stack', 'Full-stack maturity', 'Entrega de produtos digitais escaláveis, integrações complexas e otimização de performance ponta a ponta.', 'Delivering scalable digital products, complex integrations and end-to-end performance optimization.', '["Arquitetura web","APIs","Performance"]', 4, 1);
INSERT INTO milestones (year_pt, year_en, title_pt, title_en, desc_pt, desc_en, techs, ordem, publicado) VALUES ('Hoje', 'Today', 'Clean code & evolução', 'Clean code & growth', 'Evolução contínua: boas práticas, padrões de projeto e engenharia de software para construir sistemas robustos.', 'Continuous growth: best practices, design patterns and software engineering to build robust systems.', '["Clean Code","TDD","Design Patterns"]', 5, 1);
INSERT INTO services (slug, n, image, accent, title_pt, title_en, tagline_pt, tagline_en, intro_pt, intro_en, forwho_pt, forwho_en, process, includes, tags, meta_title_pt, meta_title_en, meta_description_pt, meta_description_en, ordem, publicado) VALUES ('sites', '01', '/services/sites.webp', '#5B8DEF', 'Front-end & Interfaces', 'Front-end & Interfaces', 'Interfaces rápidas, acessíveis e bem construídas — do componente ao deploy.', 'Fast, accessible, well-built interfaces — from component to deploy.', 'Transformo design em interface de verdade: componentes reutilizáveis, performance medida (Core Web Vitals), acessibilidade e SEO técnico. Construo com React e Next.js, em TypeScript, com foco em código limpo e fácil de manter.', 'I turn design into real interfaces: reusable components, measured performance (Core Web Vitals), accessibility and technical SEO. Built with React and Next.js in TypeScript, focused on clean, maintainable code.', 'Onde eu mais agrego: times de produto que precisam de um front-end sólido, rápido e fácil de manter — do MVP ao site em escala.', 'Where I add the most value: product teams that need a solid, fast and maintainable front-end — from MVP to production-scale sites.', '[{"title":{"pt":"Descoberta","en":"Discovery"},"desc":{"pt":"Conversamos sobre o seu negócio, objetivos e público. Eu mapeio o conteúdo e a estrutura ideal antes de desenhar qualquer tela.","en":"We talk about your business, goals and audience. I map out the content and the ideal structure before designing a single screen."}},{"title":{"pt":"Design","en":"Design"},"desc":{"pt":"Crio um layout exclusivo no estilo editorial, com identidade própria, tipografia forte e foco total na leitura e na conversão.","en":"I craft an exclusive editorial-style layout, with its own identity, strong typography and full focus on readability and conversion."}},{"title":{"pt":"Desenvolvimento","en":"Development"},"desc":{"pt":"Codifico tudo com Next.js e React: rápido, responsivo em qualquer tela e com SEO técnico desde a base.","en":"I build everything with Next.js and React: fast, responsive on any screen and with technical SEO from the ground up."}},{"title":{"pt":"Publicação","en":"Launch"},"desc":{"pt":"Coloco no ar, configuro domínio, analytics e deixo tudo pronto pro mundo ver — com acompanhamento após o lançamento.","en":"I take it live, set up the domain and analytics, and leave everything ready for the world to see — with post-launch support."}}]', '[{"pt":"Design exclusivo (sem templates prontos)","en":"Exclusive design (no off-the-shelf templates)"},{"pt":"100% responsivo (celular, tablet e desktop)","en":"Fully responsive (mobile, tablet and desktop)"},{"pt":"SEO técnico e dados estruturados","en":"Technical SEO and structured data"},{"pt":"Performance e carregamento rápido","en":"Performance and fast loading"},{"pt":"Formulário de contato integrado","en":"Integrated contact form"},{"pt":"Publicação e configuração de domínio","en":"Deployment and domain setup"}]', '["React","Next.js","TypeScript","Tailwind","Framer Motion"]', 'Front-end & Interfaces — React e Next.js', 'Front-end & Interfaces — React and Next.js', 'Desenvolvimento front-end com React, Next.js e TypeScript: componentes reutilizáveis, performance (Core Web Vitals), acessibilidade e SEO técnico.', 'Front-end development with React, Next.js and TypeScript: reusable components, performance (Core Web Vitals), accessibility and technical SEO.', 0, 1);
INSERT INTO services (slug, n, image, accent, title_pt, title_en, tagline_pt, tagline_en, intro_pt, intro_en, forwho_pt, forwho_en, process, includes, tags, meta_title_pt, meta_title_en, meta_description_pt, meta_description_en, ordem, publicado) VALUES ('sistemas', '02', '/services/sistemas.webp', '#34D399', 'Sistemas & APIs', 'Systems & APIs', 'Back-end, painéis e APIs REST — da modelagem do banco ao deploy.', 'Back-end, dashboards and REST APIs — from database modeling to deploy.', 'Construo aplicações completas: autenticação, CRUD, dashboards, relatórios e APIs REST sobre banco relacional. Modelo os dados, escrevo a lógica de negócio e exponho endpoints seguros e bem documentados.', 'I build complete applications: authentication, CRUD, dashboards, reports and REST APIs over a relational database. I model the data, write the business logic and expose secure, well-documented endpoints.', 'Onde eu mais agrego: produtos que precisam de um back-end confiável e um painel de administração sob medida, integrados ao front-end.', 'Where I add the most value: products that need a reliable back-end and a custom admin panel, integrated with the front-end.', '[{"title":{"pt":"Mapeamento","en":"Mapping"},"desc":{"pt":"Entendo o seu fluxo de trabalho atual e identifico o que pode ser automatizado e centralizado.","en":"I understand your current workflow and identify what can be automated and centralized."}},{"title":{"pt":"Arquitetura","en":"Architecture"},"desc":{"pt":"Modelo o banco de dados e a estrutura do sistema, definindo telas, permissões e regras de negócio.","en":"I model the database and the system structure, defining screens, permissions and business rules."}},{"title":{"pt":"Desenvolvimento","en":"Development"},"desc":{"pt":"Construo o painel com autenticação, CRUD, relatórios e as integrações que a sua operação precisa.","en":"I build the dashboard with authentication, CRUD, reports and the integrations your operation needs."}},{"title":{"pt":"Treinamento & Suporte","en":"Training & Support"},"desc":{"pt":"Entrego com treinamento da equipe e acompanhamento para garantir que tudo rode liso no dia a dia.","en":"I deliver with team training and follow-up to make sure everything runs smoothly day to day."}}]', '[{"pt":"Painel administrativo personalizado","en":"Custom admin panel"},{"pt":"Login seguro e níveis de acesso","en":"Secure login and access levels"},{"pt":"Cadastros e gestão de dados (CRUD)","en":"Records and data management (CRUD)"},{"pt":"Relatórios e indicadores","en":"Reports and metrics"},{"pt":"Integrações via API","en":"API integrations"},{"pt":"Banco de dados estruturado","en":"Structured database"}]', '["Node.js","PHP","MySQL","REST APIs"]', 'Sistemas & APIs — back-end e painéis', 'Systems & APIs — back-end and dashboards', 'Desenvolvimento de sistemas, painéis administrativos e APIs REST com autenticação, CRUD e banco de dados relacional.', 'Development of systems, admin dashboards and REST APIs with authentication, CRUD and a relational database.', 1, 1);
INSERT INTO services (slug, n, image, accent, title_pt, title_en, tagline_pt, tagline_en, intro_pt, intro_en, forwho_pt, forwho_en, process, includes, tags, meta_title_pt, meta_title_en, meta_description_pt, meta_description_en, ordem, publicado) VALUES ('lojas', '03', '/services/lojas.webp', '#F59E0B', 'E-commerce & Integrações', 'E-commerce & Integrations', 'Checkout, pagamentos e integrações — performance e segurança em primeiro lugar.', 'Checkout, payments and integrations — performance and security first.', 'Construo fluxos de e-commerce com catálogo, carrinho, checkout e integração de pagamentos (gateways e webhooks), além de controle de estoque. Foco em performance, segurança e uma experiência de compra que converte.', 'I build e-commerce flows with catalog, cart, checkout and payment integrations (gateways and webhooks), plus stock control. Focused on performance, security and a buying experience that converts.', 'Onde eu mais agrego: projetos que precisam conectar front-end, pagamentos e serviços externos num fluxo de compra confiável e rápido.', 'Where I add the most value: projects that need to connect front-end, payments and external services into a reliable, fast checkout flow.', '[{"title":{"pt":"Catálogo","en":"Catalog"},"desc":{"pt":"Organizamos produtos, categorias, variações e preços de forma clara e fácil de gerenciar.","en":"We organize products, categories, variations and prices in a clear, easy-to-manage way."}},{"title":{"pt":"Design da loja","en":"Store design"},"desc":{"pt":"Crio uma vitrine atraente e fácil de navegar, com foco em destacar produtos e guiar até a compra.","en":"I create an attractive, easy-to-navigate storefront focused on highlighting products and guiding to checkout."}},{"title":{"pt":"Pagamento & Estoque","en":"Payment & Stock"},"desc":{"pt":"Integro pagamento seguro e controle de estoque, com painel para acompanhar pedidos e vendas.","en":"I integrate secure payment and stock control, with a panel to track orders and sales."}},{"title":{"pt":"Lançamento","en":"Launch"},"desc":{"pt":"Publico a loja, testo todo o fluxo de compra e otimizo cada etapa para reduzir abandono de carrinho.","en":"I launch the store, test the full purchase flow and optimize every step to reduce cart abandonment."}}]', '[{"pt":"Catálogo de produtos e categorias","en":"Product and category catalog"},{"pt":"Carrinho e checkout otimizado","en":"Cart and optimized checkout"},{"pt":"Pagamento online seguro","en":"Secure online payment"},{"pt":"Controle de estoque","en":"Stock control"},{"pt":"Painel de pedidos e vendas","en":"Orders and sales dashboard"},{"pt":"Otimização de conversão","en":"Conversion optimization"}]', '["E-commerce","Pagamentos","Webhooks","Integrações"]', 'E-commerce & Integrações — checkout e pagamentos', 'E-commerce & Integrations — checkout and payments', 'Desenvolvimento de e-commerce e integrações: catálogo, checkout, pagamentos (gateways e webhooks) e controle de estoque, com foco em performance e conversão.', 'E-commerce and integrations development: catalog, checkout, payments (gateways and webhooks) and stock control, focused on performance and conversion.', 2, 1);
INSERT INTO section_content (chave, tipo, valor) VALUES ('about.bio', 'text', '{"pt":"Sou Luiz Antônio, desenvolvedor front-end nascido e criado no interior de Minas Gerais. Percorro 100 km por dia para cursar Bacharelado em Sistemas de Informação na UNIVÁS, e atuo com desenvolvimento e web design há mais de dois anos — sempre em busca de evolução constante.","en":"I\'m Luiz Antônio, a front-end developer born and raised in the countryside of Minas Gerais, Brazil. I travel 100 km a day to study for a Bachelor\'s in Information Systems at UNIVÁS, and I\'ve worked with development and web design for over two years — always chasing constant growth."}');
INSERT INTO section_content (chave, tipo, valor) VALUES ('about.story.quote', 'text', '{"pt":"Enfrentei dificuldades, mas pude crescer e aprender o que significa realmente ter uma família.","en":"I faced hardships, but I was able to grow and learn what it truly means to have a family."}');
INSERT INTO section_content (chave, tipo, valor) VALUES ('about.story.paragraphs', 'list', '{"pt":["Minha história é marcada por desafios e superações. Meus pais eram surdos e mudos, mas não herdei essa condição. Quando eu tinha apenas dois anos, minha mãe faleceu, e fui encontrado chorando ao seu lado.","Meu pai, que não podia cuidar de mim sozinho, me deixou aos cuidados dos meus avós, e fui separado da minha irmã — algo que me marcou profundamente. Pouco tempo depois, ele sofreu um acidente a caminho do hospital e entrou em coma. Resistiu por um tempo, mas não tive a oportunidade de me despedir; guardo dele apenas as memórias.","Na infância eu era uma criança rebelde, que passava boa parte do tempo na rua. Quando fui morar com minha tia e meu tio — que considero meus pais —, dei muito trabalho, mas fui educado com amor e paciência.","Enfrentei dificuldades na escola e cheguei a repetir de ano para conseguir acompanhar os estudos. Mas, com o apoio incondicional da minha família, aprendi o que significa, de verdade, ter um lar.","Hoje sou grato por ter a minha tia Edmara e o meu tio João como pais, e meu irmão adotivo, Edu, que tanto admiro. Toda essa trajetória é o combustível que me faz percorrer 100 km diários e entregar sempre o meu melhor na tecnologia."],"en":["My story is marked by challenges and resilience. My parents were deaf and mute, but I didn\'t inherit that condition. When I was only two years old, my mother passed away, and I was found crying by her side.","My father, who couldn\'t care for me on his own, left me in my grandparents\' care, and I was separated from my sister — something that deeply affected me. Soon after, he suffered an accident on the way to the hospital and fell into a coma. He held on for a while, but I never got the chance to say goodbye; all I have left of him are memories.","As a child I was rebellious, spending much of my time out on the streets. When I went to live with my aunt and uncle — whom I consider my parents — I gave them a lot of trouble, but they raised me with love and patience.","I struggled at school and even had to repeat a year to keep up with my studies. But with my family\'s unconditional support, I learned what it truly means to have a home.","Today I\'m grateful to have my aunt Edmara and my uncle João as parents, and my adoptive brother, Edu, whom I admire so much. This whole journey is the fuel that drives me to travel 100 km a day and always deliver my best in technology."]}');
INSERT INTO section_content (chave, tipo, valor) VALUES ('about.facts', 'facts', '[{"label":{"pt":"Base","en":"Based in"},"value":{"pt":"Minas Gerais, Brasil","en":"Minas Gerais, Brazil"}},{"label":{"pt":"Formação","en":"Studying"},"value":{"pt":"Sistemas de Informação (UNIVÁS)","en":"Information Systems (UNIVÁS)"}},{"label":{"pt":"Foco","en":"Focus"},"value":{"pt":"Front-end & produtos web","en":"Front-end & web products"}},{"label":{"pt":"Desde","en":"Since"},"value":{"pt":"2021","en":"2021"}}]');
